CREATE OR REPLACE FUNCTION create_profile()
RETURNS TRIGGER AS $$
BEGIN
    -- Check if the WebsiteUrl contains 'http://' and ends with '.com'
    IF NEW.WebsiteUrl LIKE 'http://%com' THEN
        -- Extract the domain part before '.com'
        INSERT INTO profiles (Id, CreationDate, WebsiteUrl)
        VALUES (NEW.id, NEW.creationdate, 
                split_part(split_part(NEW.WebsiteUrl, '/', 3), '.', 1));
    ELSE
        RAISE EXCEPTION 'Invalid WebsiteUrl format';
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Create the trigger
CREATE TRIGGER trg_create_profile
AFTER INSERT ON users
FOR EACH ROW EXECUTE FUNCTION create_profile();

